async function upscaleImageAI(file,scale){
 if(!file)throw Error('Pilih gambar terlebih dahulu.');
 $('status').textContent='Memuat mesin AI upscale. Unduhan model pertama sekitar 44 MB untuk 2x dan lebih besar untuk 4x; model akan tersimpan di cache browser.';
 const {pipeline}=await import('https://esm.sh/@huggingface/transformers@3.8.1');
 const model=scale===4?'Xenova/swin2SR-classical-sr-x4-64':'Xenova/swin2SR-lightweight-x2-64';
 if(!aiUpscalePipelines[model]){
   aiUpscalePipelines[model]=await pipeline('image-to-image',model,{device:'wasm'});
 }
 $('status').textContent=`AI Upscale ${scale}x sedang memproses gambar...`;
 const raw=await aiUpscalePipelines[model](file);
 if(!raw||!raw.data||!raw.width||!raw.height)throw Error('Model AI tidak mengembalikan gambar yang valid.');
 const canvas=document.createElement('canvas');canvas.width=raw.width;canvas.height=raw.height;
 const ctx=canvas.getContext('2d');
 const rgba=new Uint8ClampedArray(raw.width*raw.height*4);
 for(let i=0,j=0;i<raw.data.length;i+=raw.channels,j+=4){
   rgba[j]=raw.data[i];rgba[j+1]=raw.data[i+1]??raw.data[i];rgba[j+2]=raw.data[i+2]??raw.data[i];rgba[j+3]=255;
 }
 ctx.putImageData(new ImageData(rgba,raw.width,raw.height),0,0);
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Gagal membuat file hasil.')),'image/png'));
 const url=URL.createObjectURL(blob);
 $('previewArea').innerHTML=`<img alt="Hasil AI Upscale ${scale}x" src="${url}"><p class="hint">Diproses dengan model Swin2SR ${scale}x di browser.</p>`;
 show('previewArea');
 result(`AI Upscale ${scale}x berhasil. Resolusi hasil: ${raw.width} × ${raw.height}.`,'hasil-ai-upscale-'+scale+'x.png',blob);
}

