function setupInpaintMask(file){
 const canvas=$('maskCanvas');if(!canvas||!file)return;
 const bmp=new Image();bmp.onload=()=>{
   const max=1200,scale=Math.min(1,max/Math.max(bmp.naturalWidth,bmp.naturalHeight));
   canvas.width=Math.max(1,Math.round(bmp.naturalWidth*scale));canvas.height=Math.max(1,Math.round(bmp.naturalHeight*scale));
   const ctx=canvas.getContext('2d');ctx.drawImage(bmp,0,0,canvas.width,canvas.height);
   const mask=document.createElement('canvas');mask.width=canvas.width;mask.height=canvas.height;window.__dafzzMask=mask;window.__dafzzMaskCtx=mask.getContext('2d');
   window.__dafzzMaskCtx.lineCap='round';window.__dafzzMaskCtx.lineJoin='round';
   window.__dafzzMaskCtx.strokeStyle='#fff';window.__dafzzMaskCtx.fillStyle='#fff';
   window.__dafzzBaseImage=bmp;
   let drawing=false,last=null;
   const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};
   const paint=(a,b)=>{const m=window.__dafzzMaskCtx;m.lineWidth=Math.max(8,Number($('maskBrush')?.value||28))*canvas.width/r.width;if(Math.abs(a.x-b.x)+Math.abs(a.y-b.y)<.5){m.beginPath();m.arc(a.x,a.y,m.lineWidth/2,0,Math.PI*2);m.fill();}else{m.beginPath();m.moveTo(a.x,a.y);m.lineTo(b.x,b.y);m.stroke();}const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);c.drawImage(bmp,0,0,canvas.width,canvas.height);c.save();c.globalAlpha=.45;c.drawImage(mask,0,0);c.restore();};
   let r=canvas.getBoundingClientRect();
   canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);last=point(e);paint(last,last)};
   canvas.onpointermove=e=>{if(!drawing)return;const next=point(e);paint(last,next);last=next};
   canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;last=null};
   $('status').textContent='Foto siap. Tandai area yang ingin dihapus dengan kuas.';
 };
 bmp.src=URL.createObjectURL(file);
}
